$assembly=[Reflection.Emit.AssemblyBuilder]::DefineDynamicAssembly([Reflection.AssemblyName]::new('SelectedConverterSpy'),[Reflection.Emit.AssemblyBuilderAccess]::Run);$module=$assembly.DefineDynamicModule('main');$builder=$module.DefineType('SelectedConverterSpy',[Reflection.TypeAttributes]::Public);$builder.AddInterfaceImplementation([Runtime.Serialization.IFormatterConverter]);$null=$builder.DefineDefaultConstructor([Reflection.MethodAttributes]::Public);$calls=$builder.DefineField('Calls',[int],[Reflection.FieldAttributes]::Public);$last=$builder.DefineField('Last',[string],[Reflection.FieldAttributes]::Public);$throwField=$builder.DefineField('ThrowConverter',[bool],[Reflection.FieldAttributes]::Public);$markerField=$builder.DefineField('Marker',[object],[Reflection.FieldAttributes]::Public);$seenField=$builder.DefineField('SeenType',[type],[Reflection.FieldAttributes]::Public)
